ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_story_1"] = {
{"p_story_civ_diner_eggs","story",2,"reg=civilian,family,worker,rescue",{1,"Friday morning I was pouring coffee at the diner on 31W - same regulars as always",2,"Before it started",1,"Right up to the minute - Mr. Haskins ordered his eggs over easy and the sirens began while the grill was still hot",2,"Did he get his eggs?",1,"I left them on the pass, they're probably still sitting there, going green",2,"I hope somebody ate them, he'd have wanted that",1,"He tipped a dollar every day for nineteen years, nobody tips a dollar anymore"}},
{"p_story_civ_bread_route","story",2,"reg=civilian,family,worker,rescue|world=vehicle,building,road",{1,"I drove a bread truck out of Elizabethtown, four in the morning, every morning",2,"You must have known every road in the county",1,"Every road, every dog, every gas station with a good bathroom - you learn who's up early",2,"Who was?",1,"Old men, mostly, they'd be on their porches in the dark with a cigarette, waiting for a delivery that was never for them",2,"I wonder if any of them are still sitting there",1,"I don't drive that way, I'd rather remember it with the porch lights on"}},
{"p_story_civ_church_bake","story",2,"reg=civilian,family,worker,rescue|world=building",{1,"Third Sunday of the month, fried chicken and pie in the church basement - forty women, one oven",2,"The pie fights",1,"There was no fighting, there was a lot of sighing and one cold war over a coconut cream",2,"Who won?",1,"Mavis, because she'd lie about the recipe and nobody could copy her - she took it with her",2,"I'd trade this whole pack for one slice of that",1,"Get in line behind me"}},
{"p_story_civ_dad_truck","story",2,"reg=civilian,family,worker,rescue|world=vehicle,rain",{1,"My dad had a Ford with no radio, he sang the whole way to school, off key, every single day",2,"Mine drove me nuts about the seat belt, pulled on it even after it clicked",1,"I used to slide down so nobody would see me in that truck",2,"And now?",1,"Now I'd ride in the bed in the rain just to hear him - off key and everything",2,"Yeah, yeah, me too"}},
{"p_story_civ_first_night_basement","story",2,"reg=civilian,family,worker,rescue|hour=4,9|world=door,stairs,building",{1,"First night, I took the kids down to the basement and sat against the furnace - four hours I didn't breathe right",2,"Did they sleep?",1,"The little one did, the older one stared at the stairs the whole time",2,"Smart kid",1,"He asked me at dawn if the monsters could open doors - I said no, I didn't know that",2,"And then?",1,"Then the neighbor knocked, same as always, a pot of coffee in his hand - that was the last good cup"}},
{"p_story_civ_tobacco_barn","story",2,"reg=civilian,family,worker,rescue|world=fire,road",{1,"Fifteen summers hanging tobacco in my uncle's barn, hundred degrees, leaves sticking to your arms",2,"I hated that smell",1,"I thought so too, now I'd pay a lot of cans for one lungful of it",2,"It smelled like money",1,"It smelled like August, which is better",2,"What happened to the barn?",1,"Burned in the first week, I watched the smoke from the road and kept walking"}},
{"p_story_civ_school_bus","story",2,"reg=civilian,family,worker,rescue|world=vehicle,window,water",{1,"Seven years driving a school bus, route fourteen, past the lake",2,"Rowdy kids?",1,"Terrible - Spitballs, shoes out the window, one boy who sang the same song every morning",2,"Drove you crazy",1,"Drove me crazy for seven years, I'd hear that song once more and cry like a baby",2,"Which song?",1,"Some country thing about a truck and a dog, I never learned the name"}},
{"p_story_civ_grandma_quilt","story",2,"reg=civilian,family,worker,rescue",{1,"Grandma made a quilt from every shirt my granddad ever wore - forty years of flannel",2,"Where is it now?",1,"On a bed in Radcliff, in a house I can't go back to",2,"Maybe it's still holding up",1,"Those stitches would hold up through anything, she sewed like she was angry at the cloth",2,"She sounds like a hard woman",1,"She was soft as a biscuit, she just never wanted you to know"}},
{"p_story_civ_fishing_pond","story",2,"reg=civilian,family,worker,rescue|world=water",{1,"There's a pond behind my parents' place, catfish the size of a man's arm",2,"Did you ever land one?",1,"Once - Dad took a picture, I looked like I'd won a war",2,"I'd love a picture",1,"Polaroid, in my wallet, it's all faded, I can barely see him",2,"May I?",1,"Later, when I can stand to have it out of my pocket"}},
{"p_story_civ_nurse_shift","story",2,"reg=civilian,family,worker,rescue",{1,"I worked nights at the hospital in Elizabethtown, twelve-hour shifts, three hours of sleep",2,"How was it, those first days?",1,"They came in bleeding and we called it the flu until the third bite - then there wasn't any more calling it anything",2,"How many did you lose?",1,"I stopped counting around sixty, I kept a little tally on my wrist, and then I ran out of wrist",2,"I'm sorry",1,"Everyone I knew in that building would've done the same - that's the only thing I hold onto"}},
{"p_story_civ_volunteer_fire","story",2,"reg=civilian,family,worker,rescue|world=vehicle,water",{1,"Volunteer fire department, West Point, twelve of us, one truck, a lot of coffee",2,"Busy?",1,"Mostly cats and chimneys, once a cow in a creek",2,"A cow?",1,"Four hours, three ropes, and a farmer who cried when we got her out - best call of my life",2,"Better than the fires?",1,"Better than the fires, nobody died on that one"}},
{"p_story_civ_wedding_dance","story",2,"reg=civilian,family,worker,rescue|world=window,building",{1,"We danced at the VFW hall in March, the year before - cheap punch and a DJ with a broken speaker",2,"Who was the lucky man?",1,"Dale, he stepped on my foot four times and said sorry every time",2,"Where's Dale?",1,"He went out for firewood on the ninth day, I waited at the window",2,"I'm so sorry",1,"He'd want me to keep dancing, I do, in the kitchen, when nobody's watching"}},
{"p_story_civ_mechanic_chevy","story",2,"reg=civilian,family,worker,rescue",{1,"I rebuilt a seventy-two Chevy once, took me six years of Saturdays",2,"Did it run?",1,"Like a dream, drove it to the county fair, won a ribbon, sold it to a man from Paducah",2,"Why on earth would you sell it?",1,"Needed the money for the baby, never regretted it, sometimes regretted it",2,"Which?",1,"Both, it depends on the weather"}},
{"p_story_civ_first_gun","story",2,"reg=civilian,family,worker,rescue",{1,"My father took me squirrel hunting when I was ten - I cried when I hit one",2,"And then?",1,"He sat me down on a log and told me it was all right to be sorry - that sorry was a good sign",2,"Smart man",1,"Last week I put down someone's mother and I haven't spoken since - he's why I'm still able to feel anything",2,"You're still talking to me",1,"A little, thanks for that"}},
{"p_story_civ_louisville_trip","story",2,"reg=civilian,family,worker,rescue",{1,"We drove up to Louisville every Christmas to see the lights downtown - whole family in the station wagon",2,"I remember the lights",1,"My sister got carsick every year without fail, we kept a bucket under her seat",2,"Poor thing",1,"She's up there now, somewhere, I keep hoping she kept the bucket",2,"Wherever she is, she's laughing about it",1,"God, I hope so"}},
{"p_story_civ_school_teacher","story",2,"reg=civilian,family,worker,rescue",{1,"I taught fifth grade for twenty-two years - math, mostly",2,"Which means you can divide the cans fairly",1,"Which means I got to watch ten-year-olds learn the thing they swore they'd never learn - fractions",2,"Do you miss it?",1,"Every day, mostly the ones who gave me trouble - they're the ones I remember",2,"Any of them still around?",1,"One, I think, found him in Muldraugh last week, bigger than me, and he still called me ma'am"}},
{"p_story_civ_old_dog","story",2,"reg=civilian,family,worker,rescue|world=building",{1,"We had a beagle named Biscuit, fat, loud, ate a whole pie once",2,"What happened to him?",1,"He barked at the first one that came up the driveway - I let him out, I never saw him again",2,"He was brave",1,"He was stupid and brave, I loved him for both",2,"Maybe he's still out there, eating pie",1,"I'll let myself believe that, thanks"}},
{"p_story_civ_radio_shop","story",2,"reg=civilian,family,worker,rescue|world=vehicle",{1,"Repaired radios at a shop on Main Street, cassette decks, car stereos, whatever",2,"Handy now",1,"You'd think, I can fix a deck in an hour but I can't get a signal to say anything but static",2,"Nobody's left on the air",1,"There's somebody, sometimes at night I catch a voice under the noise - always reading numbers",2,"Numbers?",1,"Digits, like a code, I wrote some down, haven't worked out the key yet"}},
{"p_story_civ_prom_night","story",2,"reg=civilian,family,worker,rescue|hour=20,5|world=vehicle,door",{1,"Prom, nineteen eighty-eight, I wore my mother's dress and a corsage the size of a cabbage",2,"Who took you?",1,"Tommy Beasley, he cried when he saw me in the doorway - not for me, his date had cancelled and I was the backup",2,"Ouch",1,"He's the only boy who ever danced with me that whole night - I forgave him by midnight",2,"Where's Tommy now?",1,"Somewhere, trying to fix a tire, probably, he'd never ask for help"}},
{"p_story_civ_neighbor_garden","story",2,"reg=civilian,family,worker,rescue",{1,"My neighbor grew the best tomatoes in the county, never shared the secret",2,"Secret?",1,"Eggshells and coffee grounds, I found out, she told me in the hospital",2,"I'm sorry",1,"It was a long time before all this - Pancreatic, I buried the shells under my own plants every spring",2,"Do they grow?",1,"Somewhere, I haven't been back, but I'd like to think so"}},
{"p_story_civ_church_choir","story",2,"reg=civilian,family,worker,rescue|world=water",{1,"Alto in the choir at Mount Zion - eleven years",2,"Can you still sing?",1,"Not out loud - not here",2,"Hum something",1,"All right - quietly, it's a hymn my grandmother liked, about a river",2,"That's lovely - don't stop",1,"I'll stop when the words run out, and they never do"}},
{"p_story_civ_ice_storm","story",2,"reg=civilian,family,worker,rescue|world=building,road,winter",{1,"Winter of eighty-nine, ice took down every line in Hardin County - eleven days without power",2,"You got through that",1,"We lived in the kitchen with the oven open, the whole street sharing soup - best winter I remember",2,"I'd remember being cold, not the soup",1,"Everybody was cold and everybody showed up, that's what this winter could be, if we let it",2,"I'd like that",1,"Me too, hand me that pot"}},
{"p_story_civ_first_car","story",2,"reg=civilian,family,worker,rescue|world=vehicle,road",{1,"My first car was a Pinto that backfired at stop signs - cost me four hundred dollars",2,"It exploded?",1,"Never once, it just scared the old women crossing the road",2,"Did you keep it?",1,"Sold it for scrap and cried in the parking lot - I should have kept the horn",2,"Why the horn?",1,"It played the first four notes of \"La Cucaracha.\" I miss it more than the car"}},
{"p_story_civ_widow_ring","story",2,"reg=civilian,family,worker,rescue",{1,"I still wear his ring, on a chain, under the shirt",2,"How long ago?",1,"Before, a heart attack in the fall - so I thought I was one of the lucky ones, that I'd already done my losing",2,"Does it get easier to carry?",1,"It gets quieter, the weight never changes",2,"I'm glad you told me",1,"I wasn't sure I would, the fire helps"}},
{"p_story_civ_summer_camp","story",2,"reg=civilian,family,worker,rescue|world=vehicle",{1,"I was a counselor at a camp on Rough River - Canoes, archery, a cook named Pearl",2,"Pearl?",1,"Six feet tall, hands like frying pans, she made pancakes the size of hubcaps and ruled the whole camp",2,"I bet nobody misbehaved",1,"Nobody dared, we were all terrified of her and all in love with her",2,"What happened to Pearl?",1,"She took the last boat out, with the little ones, singing - that's the last I saw of her"}},
{"p_story_civ_barber","story",2,"reg=civilian,family,worker,rescue",{1,"Twenty years behind a chair, everyone tells their business to a barber",2,"Secrets?",1,"Nothing I can repeat, but I can say who was cheating, who was drinking, and who was going to run for sheriff",2,"Which one ran?",1,"The drinker, won in a landslide - people like a man with a flaw",2,"Is he still alive?",1,"Last I heard, he was holding the courthouse, not bad for a drunk"}},
{"p_story_civ_sunday_drive","story",3,"reg=civilian,family,worker,rescue",{1,"Sunday drives with Granddad, he'd narrate every barn like he'd built it",2,"Every barn?",3,"I remember that, he'd say \"that one leans, but it leans with pride\"",1,"Always the same line",2,"I never knew him, but I'd have liked to",3,"You'd have gotten a lecture about barns, and a peppermint",1,"He always had a peppermint, in his shirt pocket, wrapped in wax paper"}},
{"p_story_civ_kitchen_table","story",3,"reg=civilian,family,worker,rescue",{1,"Mom cooked for nine people every night and set a place for the dog",2,"The dog?",3,"He was the tenth - don't argue with her",1,"Sat in his own chair, I swear, and begged during grace",2,"How do you do grace with a begging dog?",3,"Loud, quick, and with one hand under the table",1,"Amen, pass the beans"}},
{"p_story_civ_town_council","story",2,"reg=civilian,family,worker,rescue",{1,"I sat on the Muldraugh town council, eleven of us arguing about a stoplight for two years",2,"Did you get the light?",1,"We got the light, the week before it all went wrong - it worked for five days",2,"At least it worked",1,"It's still blinking out there, red, red, red, a very patient light",2,"Maybe it knows something we don't",1,"It knows to keep waiting"}},
{"p_story_civ_lost_cat","story",2,"reg=civilian,family,worker,rescue",{1,"I lost a cat named Pepper when I was seven - cried for a week",2,"Did she come back?",1,"Two years later, fat and happy, three blocks over, a family had been feeding her, she wouldn't look at me",2,"Cats",1,"I forgave her, I just never forgot",2,"So what's that teach you, you reckon?",1,"Something about hoping, I think, hoping and being let down and hoping anyway"}},
{"p_story_civ_pie_contest","story",2,"reg=civilian,family,worker,rescue",{1,"Strawberry pie, county fair, nineteen ninety-one, I came in second",2,"Second isn't bad",1,"Second to a woman who used canned filling, I've never forgiven the judges",2,"Did you fight them?",1,"I wrote a letter - four pages, I never mailed it, it's in a drawer in Radcliff",2,"You should go get it",1,"That drawer is the last thing I'd go back for, which tells you something about me"}},
{"p_story_civ_phone_call","story",2,"reg=civilian,family,worker,rescue|hour=16,5",{1,"I called my brother the second day, the line rang and rang",2,"Did anybody pick up?",1,"Somebody did - breathing - no words, I said his name three times",2,"God",1,"Then the line went dead, I've never been sure if it was him or something using his phone",2,"Don't ask yourself that tonight",1,"I won't - thank you"}},
{"p_story_civ_harvest_supper","story",2,"reg=civilian,family,worker,rescue|world=road",{1,"At the end of harvest, the whole road came to our place - folding tables in the yard, sixty people",2,"Sounds loud",1,"Loud as a wedding, pork, corn, three kinds of potato salad, a fiddle",2,"A fiddle?",1,"Old Mr. Terrell, couldn't see his own hands but never missed a note",2,"That's a good memory to have",1,"It's the one I take out when the nights are long"}},
{"p_story_civ_lighthouse_story","story",2,"reg=civilian,family,worker,rescue|world=vehicle",{1,"When I was a paramedic, I once delivered a baby in the back of an ambulance on the Dixie Highway",2,"Boy or girl?",1,"Girl - eight pounds, mother laughing and swearing at the same time",2,"Did you hear from them after?",1,"A card every Christmas, name was Hope - I promise you, Hope",2,"Hard to believe a name could be that perfect",1,"I'd like to believe she's somewhere warm, walking, a pair of little shoes"}},
{"p_story_civ_rain_porch","story",2,"reg=civilian,family,worker,rescue|world=building,rain",{1,"Best thing about a Kentucky summer is a rain on the porch at four in the afternoon",2,"Hot, then it breaks",1,"The whole sky goes green, the dogs hide under the steps, and Grandpa says \"that's just God doing the dishes\"",2,"Doing the dishes",1,"He'd say it every time and every time we'd laugh like it was new",2,"Funny how the small things stay",1,"They're the only thing that does"}},
{"p_story_civ_snow_day","story",2,"reg=civilian,family,worker,rescue|world=snow",{1,"Snow days were the best, whole school closed, no questions",2,"Sled on the hill behind the school",1,"Cardboard, mostly, a trash can lid if you were rich",2,"I once went down on a baking sheet",1,"And came back with all your teeth?",2,"Mostly, we should do it again when the winter comes - just once",1,"Let's, we could use one good fall"}},
{"p_story_civ_corner_store","story",2,"reg=civilian,family,worker,rescue",{1,"Ran the corner store on Elm for thirty years, penny candy, lottery tickets, a jar of pickled eggs",2,"Pickled eggs",1,"Nobody bought them, they've been in that jar since eighty-four - mine to dust",2,"Dusted them for ten years?",1,"Eleven, I'd miss them, honestly - they were mine",2,"Seems like the jar is still there",1,"Somewhere, probably on the shelf, perfectly preserved - the only thing in town that didn't change"}},
{"p_story_civ_wild_dogs","story",2,"reg=civilian,family,worker,rescue",{1,"First week, I saw a pack of dogs go through the cornfield - twelve, maybe more, all running the same way",2,"Away from town?",1,"Away from town, I thought, if the dogs are leaving, I should be leaving",2,"Did you listen to them?",1,"Three days late, I think about those three days more than anything",2,"You're here now",1,"Because of the dogs, I owe them a steak, if I ever see a steak again"}},
{"p_story_civ_prayer_walk","story",2,"reg=civilian,family,worker,rescue",{1,"Before this I was a chaplain for the county jail - prayed with men on their worst days",2,"Did it help?",1,"Sometimes, sometimes I just held the bucket",2,"That's still help",1,"That's what I told myself, I've held a lot of buckets since",2,"I think they'd say thank you",1,"A man in cell six said it once, I'm still carrying it"}},
{"p_story_civ_threes_picnic","story",3,"reg=civilian,family,worker,rescue",{1,"Family reunion every Fourth of July at Otter Creek, hundred and fifty relatives",2,"Hundred and fifty?",3,"And one grill, uncle Roy at the grill, arguing about charcoal",1,"He'd been using the same recipe since before I was born",2,"Which was?",3,"Burn it, then apologize",1,"God, I would walk to Otter Creek for one burnt hot dog"}},
{"p_story_civ_threes_firstweek","story",3,"reg=civilian,family,worker,rescue",{1,"Where were you when the radio said stay inside?",2,"At work, the lights flickered, the foreman went white",3,"I was at my mother's, she said, \"That doesn't sound like the weather\"",1,"Smart woman",3,"She's the one who handed me the shotgun and told me to find my brothers",2,"Did you?",3,"One of them, I'm still looking for the other"}},
{"p_story_law_traffic_stop","story",2,"reg=law,swat|world=vehicle",{1,"Worst call I ever took was a traffic stop on 31W at two in the morning - a man in a pickup, forty miles over",2,"Drunk?",1,"Cold sober, his wife was in labor in the passenger seat - I led him to the hospital with the lights on",2,"Did they make it?",1,"Seven minutes to spare, he named the boy after me - I still get a card from them",2,"That's a good one",1,"It's the best one, I hold onto it on nights like this"}},
{"p_story_law_dispatch_voice","story",2,"reg=law,swat",{1,"For six years I heard the same dispatcher every night - voice like warm tea, never saw her face",2,"Did you ever meet her?",1,"Once, at a retirement party, she was shorter than I expected - wore glasses on a chain",2,"Disappointed?",1,"Not a bit, I told her she saved my life a dozen times with that voice - she laughed",2,"She sounds like a good woman",1,"Her name was Doris, I keep hoping I'll hear her on the radio"}},
{"p_story_law_first_day","story",2,"reg=law,swat|hour=16,5|world=road",{1,"The first day, we had forty officers in the county - by nightfall, nine",2,"What happened to the rest?",1,"Some stood their ground, some went home to family, I can't blame either",2,"Which were you?",1,"I stayed, told myself it was duty - truth is, nobody was waiting for me",2,"I'm sorry",1,"Don't be, it made me useful, a man with no one to go home to can hold a street"}},
{"p_story_law_k9","story",2,"reg=law,swat",{1,"I had a K9 partner named Duke - German shepherd, hundred pounds, smarter than the sergeant",2,"What happened to him?",1,"He ran toward the noise on the third day, I called him back, he didn't come",2,"He was doing his job",1,"He was, I took his tags and kept the leash, some nights I put it in my pocket and walk the perimeter",2,"Does it help?",1,"It gives my hand something to hold"}},
{"p_story_law_rookie_year","story",2,"reg=law,swat",{1,"My first week on the job, I got locked in the back of my own cruiser by a drunk who stole my keys",2,"How long?",1,"Two hours, the whole shift watched from the donut shop and took bets",2,"Brutal",1,"The sergeant bought me coffee after and said, \"Now you're one of us\"",2,"That's a decent welcome",1,"It's the only reason I stayed, you don't forget being laughed at by people who like you"}},
{"p_story_law_swat_training","story",2,"reg=law,swat|world=building,road",{1,"Our training facility was an old furniture warehouse near Fort Knox - plywood walls, a leaky roof",2,"You got used to it",1,"We'd run entries until the sun came up and then go eat at the diner across the road",2,"Same diner?",1,"Same waitress, same pie, she always asked how many we'd arrested - we always said none",2,"Because it was training",1,"Because nobody ever believed us, she slipped us extra whipped cream anyway"}},
{"p_story_law_drunk_sheriff","story",2,"reg=law,swat",{1,"Our old sheriff once arrested himself - seriously",2,"Come on",1,"Drove home from the VFW, blew a stop sign, saw the lights in his own mirror - wrote himself a ticket",2,"Did he pay it?",1,"Paid it, framed the receipt, hung it over the desk - best sheriff I ever worked for",2,"What happened to him?",1,"Cardiac, before any of this, I'm almost glad he missed it"}},
{"p_story_law_missing_girl","story",2,"reg=law,swat|world=road",{1,"I worked a missing persons case that I never closed - a girl, sixteen, outside Rosewood",2,"Never found her?",1,"Never, three years, every Sunday I drove those back roads - I think of her more than the ones I did solve",2,"Maybe she's out here",1,"That's what I tell myself, alive, somewhere, grown up, laughing",2,"It's possible",1,"It has to be, otherwise I've been driving for nothing"}},
{"p_story_law_fishing_trip","story",2,"reg=law,swat",{1,"Four of us used to take the first week of October and go fishing at Nolin Lake - no phones, no pagers",2,"No work",1,"We never caught a thing, we'd sit and argue about the Wildcats, drink coffee from a thermos",2,"Sounds like a good life",1,"It was a great life, I just didn't know it at the time",2,"Nobody does",1,"That's the cruel part"}},
{"p_story_law_kids_badge","story",2,"reg=law,swat",{1,"I gave my badge sticker to a kid once, a little boy at a bike safety rodeo",2,"What did he say?",1,"Asked if I could arrest his sister, I said not today - he looked heartbroken",2,"Sisters",1,"Years later I saw him at the grocery, grown man, a deputy himself, he stuck a sticker on my coat",2,"That's a nice circle",1,"I think about that when I'm tired, it keeps me up straight"}},
{"p_story_law_christmas_shift","story",2,"reg=law,swat|hour=16,5|world=vehicle",{1,"Every Christmas Eve I worked the late shift so the younger guys could be with their kids",2,"Quiet night?",1,"Usually, people are gentler on Christmas Eve, even the drunks",2,"Anything memorable?",1,"A woman handed me a plate of cookies through my window and said \"for the officer who's alone tonight.\" I cried in the car",2,"Still got the plate?",1,"Lost it, but I remember the cookies, oatmeal, with raisins"}},
{"p_story_law_mountain_road","story",2,"reg=law,swat",{1,"Four years ago we cleared a cabin up in the hills - a man holed up with two hostages, three days",2,"How did it end?",1,"Nobody fired, we talked him out, one of the negotiators had been his Sunday school teacher",2,"Unreal",1,"He gave up crying and asked if he could call his mother first - we said yes",2,"Good ending",1,"The best kind - Rarest, too, I'd like another one of those"}},
{"p_story_mil_basic_training","story",2,"reg=military,elite",{1,"Basic at Fort Knox, summer of eighty-nine, a drill sergeant named Ruiz who never raised his voice",2,"Quiet type?",1,"Terrifying - he'd stand six inches from your face and whisper, \"Is that your best, son?\"",2,"Was it?",1,"Never, not one time, I hated him for six weeks and thanked him at graduation",2,"Where's he now?",1,"I'd like to tell you he's alive, I don't know - I like to picture him still whispering to the dead"}},
{"p_story_mil_mess_hall","story",2,"reg=military,elite|hour=16,5",{1,"Our mess sergeant could make powdered eggs taste like a Sunday brunch - nobody could explain it",2,"Magic?",1,"Black pepper and a little hot sauce, he swore it was patience",2,"I'd take powdered eggs tonight",1,"So would I, with a cup of terrible coffee and a table of idiots who loved me",2,"Sounds like home",1,"That's what it was, I just wasn't ready to say it"}},
{"p_story_mil_letters_home","story",2,"reg=military,elite",{1,"My mother wrote me every Thursday for eleven years, four pages, both sides",2,"What about?",1,"The neighbors, the weather, who died, who was pregnant, never a word about herself",2,"Do you still have them?",1,"In a footlocker at Fort Knox, I don't know if the building's still standing",2,"Maybe it is",1,"Maybe, if it is, I'm going back for those letters before I go back for anything else"}},
{"p_story_mil_green_beret","story",2,"reg=military,elite|hour=16,22",{1,"Did a rotation overseas I can't talk about, ate rice for a month and watched a sunset I'll never describe",2,"Try",1,"Orange, then purple, then a color without a name, the whole valley went quiet like it was listening",2,"You remember that, out of everything?",1,"It's the only part I don't mind remembering, the rest I leave in the bag",2,"Fair enough",1,"Some days I think that sunset kept me human"}},
{"p_story_mil_airborne_jump","story",2,"reg=military,elite|world=door",{1,"First jump I froze in the door, a thousand feet up, wind roaring, couldn't move",2,"And?",1,"The jumpmaster put his boot against my back, I've never been so grateful to be pushed",2,"How was the fall?",1,"Quiet, once the chute opened, I could hear a dog barking in a farmyard - took me a minute to breathe",2,"I think everybody needs a boot sometimes",1,"A little shove, a lot of faith, hand me that canteen"}},
{"p_story_mil_motor_pool","story",2,"reg=military,elite|world=vehicle,cars",{1,"I was a mechanic in the motor pool - Deuce-and-a-half trucks, mostly",2,"Reliable?",1,"Reliable like a mule, they'd start in January with a prayer and a good kick",2,"Do you miss them?",1,"I miss the sound, that diesel rattle, like a washing machine full of gravel",2,"I'd listen to that all day",1,"There's one I'd like to find - number two-seven-one, she had a dent in the bumper that I never fixed"}},
{"p_story_mil_nco_wisdom","story",2,"reg=military,elite",{1,"My first sergeant used to say, \"Eat when you can, sleep when you can, and don't be a hero when you can't\"",2,"Good advice",1,"He lived to be seventy-one, died in his own recliner watching a ball game",2,"That's the dream",1,"That's the dream, I keep repeating his words in my head so I'll get to a recliner of my own",2,"You will",1,"I appreciate that, pass the rations"}},
{"p_story_mil_christmas_barracks","story",2,"reg=military,elite|world=trees",{1,"First Christmas in the barracks, we had no tree, a sergeant spray-painted a mop green and we hung socks on it",2,"Hung socks?",1,"Everyone put a surprise in one, a candy bar, a pack of gum, a letter",2,"What did you get?",1,"A photo of my own grandmother, mailed by a private who'd never met her - he'd found it in the mess",2,"How did he know it was yours?",1,"She'd written \"for my boy\" on the back, he remembered my name from roll call"}},
{"p_story_mil_river_crossing","story",2,"reg=military,elite",{1,"Training exercise, crossing the Salt River in January, waist deep, rifles over our heads",2,"Freezing",1,"My teeth rattled so hard one of the guys offered me a mouth guard",2,"Did you take it?",1,"Hell yes, we laughed so loud the instructor threatened to double the run",2,"Did he?",1,"Doubled it, we were still laughing at the finish line"}},
{"p_story_mil_first_command","story",2,"reg=military,elite",{1,"First time I had a squad of my own, I was twenty-three and shaking inside",2,"You hid it well",1,"I lied through my teeth, the older guys all knew - one of them winked and took the point without being asked",2,"Good man",1,"I never forgot that, when I lead, I try to wink at the young ones",2,"Does it work?",1,"Not as well as it did on me"}},
{"p_story_mil_dog_tags","story",2,"reg=military,elite",{1,"I keep a second set of dog tags in my pocket - a buddy's, never wore them",2,"Where is he?",1,"Out of the army in ninety-one, back in Tennessee, he mailed them to me as a joke - I never mailed them back",2,"Why not?",1,"Because he never called, I figure if I hold onto them long enough, one of us has to come find the other",2,"Maybe he will",1,"I check my pocket twice a day"}},
{"p_story_crim_prison_yard","story",2,"reg=prison,outlaw,gang,crime",{1,"Nine years in Eddyville - you want to know the best thing about prison? The library",2,"The library?",1,"Read every Western in the building - twice, cowboys never had it this bad",2,"Not cowboys",1,"The good ones don't end happy, the good ones end honest",2,"I'd take honest",1,"Me too, it's the one thing they can't take from you inside"}},
{"p_story_crim_gas_station","story",2,"reg=outlaw,raider,gang,club,crime,prison|world=vehicle",{1,"First car I stole was a Buick, sixteen, no idea how to drive stick, ran it into a ditch",2,"What did you do?",1,"Sat on the hood until the sheriff came and gave me a ride home - he bought me a Coke",2,"A Coke?",1,"Told me I had two paths and one of them ended in a ditch - I picked the ditch every time",2,"Do you regret it?",1,"Every morning, and every afternoon I do it again"}},
{"p_story_crim_biker_ride","story",2,"reg=club,outlaw,gang,raider",{1,"Best ride of my life was a run to Daytona - eleven bikes, three days, nobody dead",2,"Impressive",1,"We slept in a motel with a pool full of frogs - Bobby swam with them, said they sang",2,"Frogs sing",1,"Not like that, he swore on his mother's name",2,"Bobby still around?",1,"Last I heard he was in the water - not frogs - something else"}},
{"p_story_crim_stolen_ham","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"One time I stole a spiral ham from a church lock-in - walked out the front, under my coat",2,"Cold-blooded",1,"Got home, opened it, found a note inside - \"God sees you, so does Pastor Dave\"",2,"Ha!",1,"I put the ham back, then I stole it again later, when the lock-in was over",2,"You committed to the bit",1,"I committed to the ham"}},
{"p_story_crim_cardsharp","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"I used to run a poker game in the back of a barbershop - Thursday nights, twenty-dollar buy-in",2,"Honest game?",1,"Mostly, I only cheated the ones who deserved it",2,"Who deserved it?",1,"Anyone who bragged about winning - Pride's the best tell there is",2,"And now?",1,"Now I deal beans and bullets, the stakes are higher and nobody's bluffing"}},
{"p_story_crim_ex_wife","story",2,"reg=outlaw,raider,gang,club,crime,prison|world=vehicle,building",{1,"My ex-wife kept the dog, the house, and the good couch - I kept the truck",2,"Fair trade",1,"Got a postcard last Easter, a picture of the dog, wearing bunny ears",2,"And?",1,"I framed it, I haven't spoken to her in four years, but that dog looks happy",2,"Dogs usually do",1,"That's the only reason I haven't gone back to apologize"}},
{"p_story_crim_prison_cook","story",2,"reg=prison,outlaw,gang,crime|world=building",{1,"I was the cook in the prison kitchen, fifteen hundred meals a day, mostly beans",2,"Could you cook?",1,"I could make a bean taste like a steak if you squinted - spent my last six months teaching the new guys",2,"Taught them what?",1,"Patience, mostly - and salt, never go cheap on salt",2,"Words to live by",1,"Words to eat by, pass that pot"}},
{"p_story_crim_junkyard","story",2,"reg=outlaw,raider,gang,club,crime,prison|world=cars",{1,"Grew up in a junkyard outside Brandenburg, my uncle raised me among the wrecks",2,"Not many toys",1,"A thousand cars, every one a spaceship, a tank, a pirate ship, I never needed more",2,"What happened to the yard?",1,"Still there, I bet, cars rust slower than people do - I'd like to see it one more time",2,"Why one more time?",1,"Because it's the last place that still feels like mine"}},
{"p_story_crim_loan_shark","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"I collected debts for a man in Louisville, never once had to break a bone",2,"How?",1,"I showed up with a smile and a photograph of their kids' school - that's all it took",2,"That's low",1,"It's low, it was effective - I think about those kids sometimes",2,"Do you?",1,"More than I thought I would, funny what the end of the world does to a man's memory"}},
{"p_story_crim_mc_funeral","story",2,"reg=club,outlaw,gang,raider",{1,"We buried our president in the spring, forty bikes in a line, two miles long",2,"Respectful",1,"The whole county pulled over, old women, cops, a man with a lawnmower - everybody took off their hat",2,"That's something",1,"He'd have loved it, he'd have said we looked like a bunch of idiots",2,"Both can be true",1,"Both usually are"}},
{"p_story_crim_thief_candy","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"I stole candy from the drugstore as a kid, never got caught - not once",2,"How?",1,"The pharmacist was my uncle, he watched me steal for years and never said a word",2,"Why?",1,"Told me at his funeral, he'd been paying for every piece out of his own pocket",2,"That's a hell of a thing",1,"I haven't taken anything since without thinking of him, well, almost anything"}},
{"p_story_crim_boot_camp","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Shock camp, nineteen eighty-seven, ninety days of dirt and yelling",2,"Did it work?",1,"For about a month, then I figured out how to game it and went right back",2,"Impressive",1,"Not really, the only thing it taught me was to mop faster",2,"Any good memories?",1,"A drill instructor once gave me a stick of gum for no reason - I chewed it for two days"}},
{"p_story_crim_ice_cream","story",2,"reg=prison,outlaw,gang,crime",{1,"I'd kill for a bowl of strawberry ice cream",2,"Don't say that",1,"Figure of speech, I'd trade you a good knife for a spoonful, though",2,"Strawberry was always the weak one",1,"Weak? It was perfect, cold, sweet, a little tart - a quiet kind of happy",2,"You're making me hungry",1,"Welcome to my life"}},
{"p_story_any_campfire_first","story",2,"",{1,"I never thought I'd get used to the quiet at night",2,"Funny, I hear more now than I ever did",1,"Crickets - wind, something far off that I don't want to name",2,"Funny how it gets to you",1,"It reminds me of camping as a kid, same smell, same stars - only the ending is different",2,"Doesn't have to be",1,"I'd like that to be true"}},
{"p_story_any_star_story","story",2,"hour=20,5",{1,"My grandfather taught me the stars on his back porch - Orion first",2,"The belt",1,"Three in a row, easiest thing to find, he said that if you can find the belt, you're never lost",2,"Is that true?",1,"It's only true if you remember to look up",2,"Let's look up",1,"Give me a second, there it is - still there"}},
{"p_story_any_lucky_coin","story",2,"",{1,"I've carried the same quarter in my pocket for twenty years - nineteen seventy-six, the bicentennial one",2,"Lucky?",1,"It hasn't done much, but it's never left me, which is better than most things",2,"May I see?",1,"Here, careful, it's got a dent from the time I bit it",2,"You bit a quarter?",1,"I was seven, I thought it'd be chocolate"}},
{"p_story_any_dream_house","story",2,"world=window,building",{1,"I dream about a house sometimes, white, green shutters, a porch swing",2,"Yours?",1,"Nobody's, I made it up - I never lived in a house like that",2,"What's inside?",1,"A kitchen with the window open and bread cooling on the sill - and a radio, playing nothing in particular",2,"Sounds nice",1,"It's the nicest place I know, and it doesn't exist"}},
{"p_story_any_old_song","story",2,"hour=16,5|world=rain",{1,"There's a song I can't get out of my head - I can't remember the name",2,"Hum it",1,"Da da dum, da da dum, something about rain",2,"That's every song ever",1,"It's the one my mother sang while she did the dishes - if I could find the words, I think I could cry",2,"You will",1,"Not tonight, I'll tell you but not tonight"}},
{"p_story_any_best_meal","story",2,"",{1,"Describe the best meal you ever had",2,"Fried chicken on a Sunday, mashed potatoes, green beans cooked in bacon, and a glass of sweet tea",1,"That's mine, too",2,"Everyone's, probably, it's the whole county in a plate",1,"With a slice of pecan pie",2,"Now you're just being cruel",1,"I'm being hopeful"}},
{"p_story_any_ghost_town","story",2,"world=building",{1,"Drove through a town last week with every porch light on - every single one",2,"Power?",1,"No power, candles, flashlights, lanterns - somebody lit them all - no bodies, no sign anyone was there",2,"Spooky",1,"I thought so too, but in the morning it felt like a prayer",2,"Whose?",1,"Whoever left, they wanted anyone passing to know they'd been loved"}},
{"p_story_any_first_snow","story",3,"world=snow,wind",{1,"Do you remember the first snow? The real one, as a kid",2,"I ate it - whole handfuls, my mother threw a fit",3,"I tried to catch it on my tongue and fell flat on my back - had the wind knocked out of me",1,"And you laughed?",3,"Hardest I ever laughed, I cried and laughed at the same time",2,"That's what being a kid is",1,"Let's try for a little of that tomorrow, if it snows"}},
{"p_story_any_old_friends","story",3,"world=door",{1,"Tell me about a friend you miss",2,"Marcus, we met in the third grade and never lost touch",3,"What was he like?",2,"Loud - funny, a terrible driver - he called me every Sunday, even when he had nothing to say",1,"Do you know where he is?",2,"I tried his house on the way here, the door was open - I left a note",3,"Then he'll find it, if he's out there",2,"That's the only thing I'm holding on to"}},
{"fw_ld4_story_a_0001","story",2,"reg=civilian,family,worker,rescue",{1,"My dad had a '78 Ford pickup, the color of dried mustard",2,"Lord, I know the kind",1,"He drove it to every one of my games, windows down, radio too loud",2,"Embarrassing?",1,"So embarrassing, I'd duck in the seat, and now I'd give my right arm to be embarrassed by that radio"}},
{"fw_ld4_story_a_0002","story",2,"reg=civilian,family,worker,rescue",{1,"First time I got drunk was on my cousin's wedding day, on blackberry wine",2,"How old were you?",1,"Fourteen, I danced with the preacher",2,"The PREACHER?",1,"Twice, I thought he was my uncle, he took it real well"}},
{"fw_ld4_story_a_0003","story",2,"reg=civilian,family,worker,rescue",{1,"There was a dog at my gas station, Pete, he waited every morning for a hot dog",2,"Did he get one?",1,"Every single day, for six years, the owner said 'Pete gets a dog'",2,"Where's Pete now?",1,"I don't know, I left in a hurry, I hope somebody's feeding him"}},
{"fw_ld4_story_a_0004","story",2,"reg=civilian,family,worker,rescue",{1,"I drove a school bus in Elizabethtown for eleven years",2,"Wow, kids?",1,"Forty-two, every morning, singing the same dumb songs",2,"Do you miss it?",1,"I miss the noise, I never thought I'd say that, God, I miss the noise"}},
{"fw_ld4_story_a_0005","story",2,"reg=civilian,family,worker,rescue",{1,"My grandmother could kill and clean a chicken in under four minutes",2,"No way",1,"She timed herself with the kitchen clock, she bet the neighbors, took their money too",2,"A real shark",1,"In an apron, with a hymnal in her pocket"}},
{"fw_ld4_story_a_0006","story",2,"reg=civilian,family,worker,rescue",{1,"I was gonna propose on the Fourth of July",2,"Oh no",1,"I had the ring, I had the speech, I had a reservation at the Kentucky Fried Chicken",2,"Oh no, no",1,"Don't laugh, it was her favorite place, and now I've got a ring and no one to give it to"}},
{"fw_ld4_story_a_0007","story",2,"reg=civilian,family,worker,rescue",{1,"Whenever my brother and I fought, Mama made us hold hands for ten minutes",2,"Sounds like a good punishment",1,"It was worse than a whipping, he had sweaty palms",2,"Did it work?",1,"Eventually we just started to like each other, can you believe that?"}},
{"fw_ld4_story_a_0008","story",2,"reg=civilian,family,worker,rescue",{1,"In school I was the kid who always forgot his lunch",2,"Poor you",1,"Mrs. Alvarez, the lunch lady, always slipped me a sandwich, never asked questions",2,"Good woman",1,"I looked for her, when this started, I never found her, but I carry a sandwich now, in case I find someone like me"}},
{"fw_ld4_story_a_0009","story",2,"reg=civilian,family,worker,rescue",{1,"First job I had was bagging groceries at the Winn-Dixie",2,"How was that?",1,"Terrible, until a lady tipped me a quarter every week, just because I carried her bags to the car",2,"Sweet",1,"I saved those quarters for a year, bought my mother a music box for Christmas"}},
{"fw_ld4_story_a_0010","story",2,"reg=civilian,family,worker,rescue",{1,"My uncle swore he saw a UFO over Fort Knox",2,"Of course he did",1,"He drew a map on a napkin, I still have it",2,"Where's it now?",1,"In my back pocket, I figure if the world's gone crazy, maybe he was right all along"}},
{"fw_ld4_story_a_0011","story",2,"reg=civilian,family,worker,rescue",{1,"You know what my husband said to me, the last time I saw him?",2,"What?",1,"'Don't forget the milk'",2,"Oh, honey",1,"I forgot, I FORGOT the milk, I've been thinking about that damn milk ever since"}},
{"fw_ld4_story_a_0012","story",2,"reg=civilian,family,worker,rescue",{1,"My daughter used to line up her stuffed animals and give them a spelling test",2,"Aw",1,"Mr. Bear failed every time, she'd give him extra homework",2,"Where's she now?",1,"Last time I saw her, asleep with all of them. I keep trying to hold that picture still"}},
{"fw_ld4_story_a_0013","story",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"After the first week I stopped counting days",2,"Why?",1,"Because counting meant there'd be a last one",2,"...I understand that",1,"Then you understand why I never ask what day it is"}},
{"fw_ld4_story_a_0014","story",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"When this started I wanted to be a hero",2,"And now?",1,"Now I want to be alive at the end of the day",2,"That's a hero, in my book",1,"That's a coward in mine, but thanks"}},
{"fw_ld4_story_a_0015","story",2,"reg=law,swat",{1,"Worst call I ever got was a cat in a tree that turned out to be a raccoon",2,"Ha, what happened?",1,"The raccoon bit the fireman, the fireman bit the cat, the cat bit me",2,"That's not how it works",1,"In Radcliff, that's exactly how it works"}},
{"fw_ld4_story_a_0016","story",2,"reg=law,swat",{1,"My first week as a deputy, I pulled over the sheriff's mother",2,"No way",1,"She was doing sixty in a thirty-five, I wrote her up, she thanked me",2,"And the sheriff?",1,"Gave me a raise, said I had a spine"}},
{"fw_ld4_story_a_0017","story",2,"reg=law,swat",{1,"I carry my dad's badge in my left pocket",2,"He was a cop?",1,"Thirty-one years, Louisville PD, he died of his heart in his chair",2,"Better than most",1,"That's what Mom says, but I'd rather he saw this, and told me what to do"}},
{"fw_ld4_story_a_0018","story",2,"reg=military,elite",{1,"Basic training, Fort Knox, summer of '87",2,"Hot as hell?",1,"A hundred and four, we ran in full gear, a kid passed out, we carried him",2,"He make it?",1,"He's a doctor now, or he was, you never know anymore"}},
{"fw_ld4_story_a_0019","story",2,"reg=military,elite",{1,"First time I saw the ocean I was nineteen, off a transport in the Gulf",2,"How was it?",1,"Huge, and gray, and then the shelling started",2,"Oh God, no",1,"But for about ten seconds there, it was the prettiest thing I ever saw"}},
{"fw_ld4_story_a_0020","story",2,"reg=military,elite",{1,"My Drill Sergeant called me 'Pencil'",2,"Why?",1,"Because I was tall and thin and always breaking at the worst moment",2,"Do you still hear it?",1,"Every time I get scared, 'Pencil, you're not made of glass'"}},
{"fw_ld4_story_a_0021","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"First car I stole was a Chevy Nova",2,"Color?",1,"Baby blue, I drove it for two weeks before I realized it had no brakes",2,"How'd you stop?",1,"I didn't, I jumped out, still got the scar"}},
{"fw_ld4_story_a_0022","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"My old man taught me three things",2,"What?",1,"How to throw a punch, how to lie to a cop, and how to hold my liquor",2,"Useful",1,"Only two out of three stuck"}},
{"fw_ld4_story_a_0023","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"I was in county when the sirens started",2,"You were INSIDE?",1,"Yeah, the guards left us locked in for two days, I ate a shoe",2,"...a shoe?",1,"Yeah, a boot, with ketchup packets, it wasn't the worst thing I've eaten"}},
{"fw_ld4_story_b_0001","story",2,"reg=civilian,family,worker,rescue",{1,"You ever hear about the time my uncle Earl tried to jump the creek on a riding mower?",2,"A riding mower?",1,"He'd had four beers and a bet, forty dollars, my aunt Dot was screaming from the porch",2,"Did he make it?",1,"He made it halfway, the mower made it all the way, he didn't",2,"Oh no",1,"He walked home soaked, holding the wheel, and Dot charged him ten dollars for the light she broke throwing a shoe"}},
{"fw_ld4_story_b_0002","story",2,"reg=civilian,family,worker,rescue",{1,"My first kiss was behind the Dairy Queen in Elizabethtown, 1979",2,"Who was the lucky girl?",1,"Peggy Lou Marcum, she tasted like cherry dip",2,"And?",1,"And her dad caught us, chased me three blocks with a garden hoe",2,"Did he catch you?",1,"Never, I was fast back then, I could outrun a hoe and a sunset",2,"What happened to Peggy Lou?",1,"She married a dentist, sent me a Christmas card every year, I hope she's alive"}},
{"fw_ld4_story_b_0003","story",2,"reg=civilian,family,worker,rescue",{1,"I want to tell you about my daughter Beth's first day of school",2,"Go ahead",1,"She cried at the bus stop, I cried in the car, we both cried at the gate",2,"Aww",1,"The teacher said 'it gets easier,' I said 'for who?'",2,"And did it?",1,"She waved at me through the window all the way down the road, and I waved until my arm fell off",2,"That's beautiful",1,"I'd wave till my arm fell off again, if she were here"}},
{"fw_ld4_story_b_0004","story",2,"reg=civilian,family,worker,rescue",{1,"The worst job I ever had was cleaning the chicken coop at Carter's farm",2,"How bad?",1,"I wore three pairs of gloves and a bandana, I still smelled like a sunburned henhouse for a week",2,"Did you quit?",1,"I quit after a rooster attacked me, and I'm not ashamed",2,"Smart rooster",1,"Smart? He bit through my boot, and I think he laughed"}},
{"fw_ld4_story_b_0005","story",2,"reg=civilian,family,worker,rescue",{1,"Back when I worked at the Kroger, we had a regular named Mr. Pettigrew",2,"The regular",1,"He bought a single banana every morning at 7:05, counted his change in pennies",2,"Every day?",1,"For fourteen years, one day he didn't come, and the whole store went quiet",2,"...what happened?",1,"He was in the hospital, I took him a banana, he cried, I cried, the manager cried, it was a mess",2,"I'd have cried too"}},
{"fw_ld4_story_b_0006","story",2,"reg=civilian,family,worker,rescue",{1,"Mama's rule at the dinner table was no elbows and no politics",2,"How'd that go?",1,"Dad broke both every Thanksgiving, then Mama would pass him the potatoes",2,"To shut him up",1,"Not at all, to give him something to chew on besides his opinions",2,"Smart woman",1,"She really was, she'd have survived this better than any of us"}},
{"fw_ld4_story_b_0007","story",2,"reg=civilian,family,worker,rescue",{1,"So I'm in the bathtub, summer of 1991, and my sister bursts in holding a snake",2,"A real one?",1,"A garter snake, she thought it was funny, I screamed so loud the neighbor called the cops",2,"Did they come?",1,"Two deputies, in my driveway, in the middle of the night, I'm in a towel, my sister is crying laughing",2,"And the snake?",1,"Bit the sergeant, I'm not kidding, he never lived it down"}},
{"fw_ld4_story_b_0008","story",2,"reg=civilian,family,worker,rescue",{1,"One time I got lost in the Mammoth Cave tour",2,"Seriously?",1,"I wandered off to look at a bat, and then the group was gone, and the lights went out",2,"Oh no",1,"Forty minutes, in the pitch dark, singing 'Amazing Grace' to keep from screaming",2,"Did they find you?",1,"A park ranger named Dwight, he said 'sir, you're about fifty feet from the exit', I thanked him and cried"}},
{"fw_ld4_story_b_0009","story",2,"reg=civilian,family,worker,rescue",{1,"Grandpa had a mule named Beauregard",2,"Beauregard?",1,"Meanest animal in Kentucky, hated everybody except Grandpa, and he only tolerated him",2,"How so?",1,"He bit the mailman, kicked the preacher, and once ate Grandma's Sunday hat",2,"And Grandpa loved him?",1,"More than us, I think, when Beauregard died Grandpa dug the grave himself, said the nicest words I ever heard him say"}},
{"fw_ld4_story_b_0010","story",2,"reg=civilian,family,worker,rescue",{1,"When I was little we played a game called 'frog or princess'",2,"How do you play?",1,"You close your eyes and your cousin puts something in your hand",2,"And you guess?",1,"Cold and slimy, frog, warm and soft, princess, I was usually wrong",2,"Ha",1,"Last time I got a dead mouse, I'm still not over it"}},
{"fw_ld4_story_b_0011","story",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"The day it started, I was stuck on I-65 for six hours",2,"The traffic?",1,"It wasn't traffic, the cars just stopped, everyone got out and looked at each other",2,"Did anyone say anything?",1,"A lady in a purple dress said 'I think we should walk,' and we all just did",2,"Just like that?",1,"Just like that, a thousand people, walking, nobody knew where, nobody said a word"}},
{"fw_ld4_story_b_0012","story",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"I found a baby once",2,"What?",1,"In a diner, behind the counter, in a box of napkins, three days old, crying",2,"Where was the mother?",1,"I never found out, I carried that little thing for two days until I found a woman with milk",2,"What happened to the baby?",1,"She took it, I never saw either again, I hope they're alive, I really hope they are"}},
{"fw_ld4_story_b_0013","story",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"You know what scared me worse than all of it?",2,"What?",1,"Not the monsters, not the guns, but the silence on the third night",2,"Why?",1,"Because that was the night I realized the phones weren't going to ring",2,"Nobody coming?",1,"Nobody, and I sat in my kitchen and listened to the refrigerator die, a long slow hum, then nothing"}},
{"fw_ld4_story_b_0014","story",2,"reg=law,swat",{1,"First night of the outbreak, I got a call about a man screaming on Church Street",2,"Was it one of them?",1,"I thought it was a drunk, I walked up with my flashlight, said 'sir, calm down'",2,"And?",1,"He turned around, and his eyes, I can't describe it, I emptied my gun and I still see his face",2,"I'm sorry",1,"Don't be, I'm the one who wasn't ready"}},
{"fw_ld4_story_b_0015","story",2,"reg=law,swat",{1,"We had a K-9 named Duke",2,"German shepherd?",1,"Belgian Malinois, smartest dog I've ever met, he could open the cruiser door with his nose",2,"Is he alive?",1,"I don't know, I had to leave him with the handler, he was on a chain, I told him to be good",2,"I'm sure he was",1,"He always was, that's the part that kills me"}},
{"fw_ld4_story_b_0016","story",2,"reg=law,swat",{1,"Funniest call I ever took, a woman reported a UFO over Radcliff",2,"And?",1,"It was a Goodyear blimp, I told her, she said 'that's what the government wants you to think'",2,"Classic",1,"I wrote it up, 'Subject believes blimp is extraterrestrial,' the chief framed it"}},
{"fw_ld4_story_b_0017","story",2,"reg=military,elite",{1,"Desert Storm, February '91, we were stuck in a ditch for two days",2,"Did it rain?",1,"It poured sideways, one guy lost his boots, another his mind",2,"What did you do?",1,"We sang, 'Country Roads,' all forty of us, in the mud, in the dark",2,"Did it help?",1,"Not a bit, but I still remember the harmony"}},
{"fw_ld4_story_b_0018","story",2,"reg=military,elite",{1,"I never told anybody this",2,"Go ahead",1,"My first night in basic, I cried in the latrine for an hour",2,"Everyone does",1,"The drill sergeant found me, he didn't yell, he just handed me a towel and said 'finish and come out'",2,"That's decent",1,"He's the reason I stayed, I think about him every time I'm scared"}},
{"fw_ld4_story_b_0019","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"First time I got locked up, I was seventeen",2,"What for?",1,"Stole a case of beer from a gas station, ran straight into a cop eating a donut",2,"Classic",1,"He didn't even stop chewing, he said 'son, you're embarrassing yourself,' and cuffed me",2,"Did you learn?",1,"I learned to check for donuts, that's about it"}},
{"fw_ld4_story_b_0020","story",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"My old man taught me to hustle pool at twelve",2,"Any good?",1,"I'd clear a table before I could drive, I made more than the mill workers",2,"What happened?",1,"One night I beat a guy who didn't like losing, he broke my cue over my head",2,"Ouch",1,"Still got the scar, and I still hustle, but now I carry a knife"}},
{"fw_ld4_story_b_0021","story",2,"reg=family",{1,"Your great-grandfather walked from Tennessee with nothing but a fiddle",2,"Did he play?",1,"Every night, by the roadside, and folks would give him a potato or a blanket",2,"What song?",1,"'Shady Grove,' he said it was the only one that made people stop and listen",2,"Do you remember it?",1,"Hum along, I'll teach you, it goes like this..."}},
}
